e2e/gallery.spec.js<pre><code>import { test, expect } from "@playwright/test";
import { contrastOf } from "./contrast.js";

for (const theme of ["light", "dark"]) {
  test.describe(`${theme} theme`, () =&gt; {
    test.beforeEach(async ({ page }) =&gt; {
      await page.emulateMedia({ reducedMotion: "reduce" });
      await page.goto("index.html");
      if (theme === "dark") {
        await page.evaluate(() =&gt; document.documentElement.classList.add("dark"));
      }
      // let colour transitions finish before measuring or screenshotting
      await page.waitForTimeout(400);
    });

    test("every variant meets 4.5:1 text contrast", async ({ page }) =&gt; {
      const results = await page.evaluate(contrastOf, "[data-test]");
      const failing = results.filter((r) =&gt; r.ratio &lt; 4.5);
      expect(failing, JSON.stringify(failing)).toEqual([]);
    });

    test("matches the visual baseline", async ({ page }) =&gt; {
      await expect(page).toHaveScreenshot(`gallery-${theme}.png`, { fullPage: true });
    });
  });
}

test("no horizontal overflow", async ({ page }) =&gt; {
  await page.goto("index.html");
  const overflow = await page.evaluate(
    () =&gt; document.documentElement.scrollWidth - document.documentElement.clientWidth
  );
  expect(overflow).toBe(0);
});

test("keyboard focus is visible, also in forced colours", async ({ page }) =&gt; {
  await page.emulateMedia({ forcedColors: "active" });
  await page.goto("index.html");
  await page.keyboard.press("Tab");
  const focused = page.locator(":focus");
  await expect(focused).toHaveAttribute("data-test", "button-primary-sm");
  await expect(focused).toHaveCSS("outline-style", "solid");
  await expect(focused).toHaveCSS("outline-width", "2px");
});
</code></pre> <p>Details that matter:</p> <ul> <li>Reduced motion and a short wait before measuring. Colour transitions were the   cause of the false 1:1 contrast result in Level 3 · 10; tests have to wait for the   final state.</li> <li>Both themes run every check.</li> <li>The focus test uses the keyboard (<code>Tab</code>), so it checks <code>:focus-visible</code> the way a   user triggers it, and it runs with forced colours emulated, the mode where ring-based   focus disappears (Level 3 · 04).</li> <li>The overflow test measures <code>scrollWidth - clientWidth</code>, the same check used for the   projects in Levels 1 and 2.</li> </ul>

